package de.tum.cit.aet.sorting;

import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

import java.lang.reflect.InvocationTargetException;
import java.util.*;

import static de.tum.in.test.api.util.ReflectionTestUtils.*;

import de.tum.in.test.api.BlacklistPath;
import de.tum.in.test.api.PathType;
import de.tum.in.test.api.StrictTimeout;
import de.tum.in.test.api.WhitelistPath;
import de.tum.in.test.api.jupiter.Public;

/**
 * @author Stephan Krusche
 * @version 5.1 (11.06.2021)
 */
@Public
@WhitelistPath("target") // mainly for Artemis
@BlacklistPath("target/test-classes") // prevent access to test-related classes and resources
class SortingExampleBehaviorTest {

    private List<Colour> colours;
    private List<Colour> coloursWithCorrectOrder;

    @BeforeEach
    void setup() {
        // create colours with specific hues for ordering
        Colour c1 = new Colour("c1", 3);
        Colour c2 = new Colour("c2", 2);
        Colour c3 = new Colour("c3", 1);
        Colour c4 = new Colour("c4", 4);

        this.colours = Arrays.asList(c1, c2, c3, c4);
        this.coloursWithCorrectOrder = Arrays.asList(c3, c2, c4, c1);
    }

    @Test
    @StrictTimeout(1)
    void testBubbleSort() {
        BubbleSort bubbleSort = new BubbleSort();
        bubbleSort.performSort(colours);
        if (!coloursWithCorrectOrder.equals(colours)) {
            fail("BubbleSort does not sort correctly");
        }
    }

    @Test
    @StrictTimeout(1)
    void testMergeSort() {
        MergeSort mergeSort = new MergeSort();
        mergeSort.performSort(colours);
        if (!coloursWithCorrectOrder.equals(colours)) {
            fail("MergeSort does not sort correctly");
        }
    }

    @Test
    @StrictTimeout(1)
    void testUseMergeSortForBigList() throws ReflectiveOperationException {
        List<Colour> bigList = new ArrayList<>();
        for (int i = 0; i < 11; i++) {
            bigList.add(new Colour("c" + i, i));
        }
        Object chosenSortStrategy = configurePolicyAndContext(bigList);
        if (!(chosenSortStrategy instanceof MergeSort)) {
            fail("The sort algorithm of Context was not MergeSort for a list with more than 10 colours.");
        }
    }

    @Test
    @StrictTimeout(1)
    void testUseBubbleSortForSmallList()  throws ReflectiveOperationException {
        List<Colour> smallList = new ArrayList<>();
        for (int i = 0; i < 3; i++) {
            smallList.add(new Colour("c" + i, i));
        }
        Object chosenSortStrategy = configurePolicyAndContext(smallList);
        if (!(chosenSortStrategy instanceof BubbleSort)) {
            fail("The sort algorithm of Context was not BubbleSort for a list with less or equal than 10 colours.");
        }
    }

    private Object configurePolicyAndContext(List<Colour> colours) throws ReflectiveOperationException {
        Object context = newInstance("de.tum.cit.aet.sorting.Context");
        invokeMethod(context, getMethod(context, "setColours", List.class), colours);

        Object policy = newInstance("de.tum.cit.aet.sorting.Policy", context);
        invokeMethod(policy, getMethod(policy, "configure"));

        Object chosenSortStrategy = invokeMethod(context, getMethod(context, "getSortAlgorithm"));
        return chosenSortStrategy;
    }
}
